}

Method.Source:
public static METTransferOrderLoadPlanningController construct()
{
    return new METTransferOrderLoadPlanningController();
}

/// <summary>
/// Initailzes the controller, sets the print management, assigns parameter values and runs the SRS report.
/// </summary>
/// <param name="_args">
/// The <c>Args</c> object.
/// </param>
public static void main(Args _args)
{
    METTransferOrderLoadPlanningController controller = METTransferOrderLoadPlanningController::construct();

    controller.parmReportName(PrintMgmtDocType::construct(PrintMgmtDocumentType::METCustActivityStatement).getDefaultReportFormat());
    controller.parmArgs(_args);
    controller.parmDialogCaption("@MET:SODTOLoadPlanReport");
    controller.startOperation();
}
